  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [240+Math.cos(t*0.4)*120, 120+Math.sin(t*0.3)*70, 0.07, 2.0, 0.09],
    [240+Math.cos(t*0.4+2.094)*120, 120+Math.sin(t*0.3+2.094)*70, 0.07, 2.0, 0.09],
    [240+Math.cos(t*0.4+4.189)*120, 120+Math.sin(t*0.3+4.189)*70, 0.07, 2.0, 0.09],
    [160+Math.sin(t*0.6)*80, 80+Math.cos(t*0.5)*50, 0.11, 1.7, 0.14],
    [320+Math.cos(t*0.55)*80, 160+Math.sin(t*0.65)*50, 0.11, 1.7, 0.14],
    [240+Math.sin(t*0.35+1)*140, 120+Math.cos(t*0.45+2)*90, 0.05, 2.5, 0.065],
