    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    iS2 += Math.sin(d*f2 + t*sp*0.4 + 3.0);
  }
  const act = aS/9, inh = iS/9, inh2 = iS2/9;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.038+t*1.0) + Math.sin((sx+sy)*0.015-t*0.5))/3
