  const reaction = Math.tanh((act - inh*0.6 - inh2*0.3 + bg*0.25 + spiral + cell)*2.0);
  const microAct = Math.sin(sx*0.2+sy*0.15-t*1.5)*0.5 + Math.sin(sx*0.15-sy*0.18+t*1.8)*0.5;
  const micro = Math.tanh((microAct - reaction*0.5)*1.5)*0.15;
  const blend = reaction*0.7 + cell*0.15 + micro*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,85],[18,95,120],[35,155,145],[120,195,160],
    [210,195,100],[230,155,75],[195,90,60],[140,45,55],[75,20,48],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15;
